import {
  ElementRef,
  inject,
  ChangeDetectionStrategy,
  Component,
  booleanAttribute,
  input,
  model,
} from '@angular/core';

@Component({
  selector: 'aevko-sidebar',
  standalone: true,
  templateUrl: './sidebar.component.html',
  styleUrl: './sidebar.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    'data-slot': 'sidebar',
    '[attr.data-collapsed]': 'collapsed()',
    '(document:keydown.escape)': 'close()',
    '(document:focusin)': 'dismissOutside($event)',
  },
})
export class AevkoSidebar {
  private readonly element = inject<ElementRef<HTMLElement>>(ElementRef);
  readonly id = input('aevko-sidebar-panel');
  readonly label = input('Primary navigation');
  readonly open = model(false);
  readonly collapsed = model(false);
  readonly closeOnNavigate = input(true, { transform: booleanAttribute });
  protected dismissOutside(event: Event): void {
    if (this.open() && !event.composedPath().includes(this.element.nativeElement))
      this.open.set(false);
  }
  protected navigate(event: MouseEvent): void {
    if (this.closeOnNavigate() && (event.target as Element).closest('a[href]')) this.close();
  }
  protected close(): void {
    if (!this.open()) return;
    this.open.set(false);
    this.element.nativeElement.querySelector<HTMLButtonElement>('.mobile-trigger')?.focus();
  }
}

:host {
  display: block;
}
aside {
  background: var(--aevko-background, #fff);
  border-inline-end: 1px solid var(--aevko-border, #e4e4e7);
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  height: 100%;
  max-width: 100%;
  min-height: 20rem;
  overflow: hidden;
  transition: width 180ms ease;
  width: 17rem;
}
aside.collapsed {
  width: 5rem;
}
.header,
.footer {
  align-items: center;
  display: flex;
  gap: 0.75rem;
  justify-content: space-between;
  padding: 1rem;
}
nav {
  display: grid;
  align-content: start;
  min-height: 0;
  gap: 0.25rem;
  overflow: auto;
  padding: 0.5rem;
}
.collapse,
.mobile-trigger {
  align-items: center;
  background: transparent;
  border: 1px solid var(--aevko-border, #e4e4e7);
  border-radius: var(--aevko-radius, 0);
  color: inherit;
  cursor: pointer;
  display: inline-flex;
  gap: 0.5rem;
  justify-content: center;
  min-height: 2.75rem;
  min-width: 2.75rem;
}
.collapse svg,
.mobile-trigger svg {
  height: 1rem;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 2;
  width: 1rem;
}
.control-icon {
  align-items: center;
  display: inline-flex;
  line-height: 0;
}
.control-icon:has(> :not(.fallback-icon)) > .fallback-icon {
  display: none;
}
.mobile-trigger,
.backdrop {
  display: none;
}
button:focus-visible,
nav:focus-visible {
  outline: 2px solid var(--aevko-focus, #a1a1aa);
  outline-offset: 1px;
}
@media (max-width: 760px) {
  .mobile-trigger {
    display: inline-flex;
  }
  .backdrop {
    background: rgb(0 0 0 / 65%);
    border: 0;
    display: block;
    inset: 0;
    position: fixed;
    z-index: 39;
  }
  aside {
    bottom: 0;
    left: 0;
    max-width: 85vw;
    position: fixed;
    top: 0;
    visibility: hidden;
    transform: translateX(-105%);
    transition: transform 180ms ease;
    width: 17rem;
    z-index: 40;
  }
  aside.open {
    visibility: visible;
    transform: translateX(0);
  }
  aside.collapsed {
    width: 17rem;
  }
}
@media (prefers-reduced-motion: reduce) {
  aside {
    transition: none;
  }
}

.header-content {
  min-width: 0;
}
aside.collapsed .header-content,
aside.collapsed .footer {
  display: none;
}
aside.collapsed .header {
  justify-content: center;
  padding: 0.75rem;
}
.collapse {
  visibility: visible;
  flex: none;
}
@media (max-width: 760px) {
  .collapse {
    display: none;
  }
  aside.collapsed .header-content,
  aside.collapsed .footer {
    display: block;
  }
}
